    {
      "card_ids": ["C06"],
      "claim": "In rats, SMB-1 showed low membrane permeability and poor CNS distribution, with low brain concentrations after subcutaneous administration.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved direct in-vivo brain-uptake records across mice, rats, and humans consistently indicate low or impermeable BBB penetration, so meaningful CNS access after systemic administration is not supported.",
